"""QQ-LUT调色 与 QQ-曲线调色：接在 LR 链尾的进阶调色，支持图像与视频。

LUT：解析 .cube（3D LUT），torch 三线性插值，按强度与原图混合。
曲线：控制点 → 256 级查表，按通道（RGB/红/绿/蓝）应用。
两者都复用 LR 的图像/视频通配处理（WslAnyType + core.video_api），保留 alpha。
"""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

import torch

from ..core.video_api import components_for_video, replace_video_frames
from .utilities import WslAnyType


# ── LUT 目录与解析 ────────────────────────────────────────────
def lut_dir() -> Path:
    """LUT 放在 user/QQ_ComfyUI_Tools/luts，升级插件不丢。"""
    try:
        import folder_paths
        base = Path(folder_paths.get_user_directory())
    except Exception:
        base = Path(__file__).resolve().parent.parent / "user"
    directory = base / "QQ_ComfyUI_Tools" / "luts"
    directory.mkdir(parents=True, exist_ok=True)
    return directory


def scan_lut_names() -> list[str]:
    try:
        names = sorted(p.name for p in lut_dir().glob("*.cube"))
    except OSError:
        names = []
    return names or ["（luts 目录为空）"]


def parse_cube(text: str) -> dict[str, Any]:
    """解析 .cube 文本 → {size, domain_min, domain_max, lut[b,g,r,3]}。"""
    size = None
    domain_min = (0.0, 0.0, 0.0)
    domain_max = (1.0, 1.0, 1.0)
    data: list[list[float]] = []
    for raw in str(text).splitlines():
        line = raw.strip()
        if not line or line.startswith("#"):
            continue
        parts = line.split()
        key = parts[0].upper()
        if key == "LUT_3D_SIZE":
            size = int(parts[1])
        elif key == "DOMAIN_MIN":
            domain_min = tuple(float(x) for x in parts[1:4])
        elif key == "DOMAIN_MAX":
            domain_max = tuple(float(x) for x in parts[1:4])
        elif key in ("TITLE", "LUT_1D_SIZE", "LUT_3D_INPUT_RANGE"):
            continue
        else:
            try:
                data.append([float(x) for x in parts[:3]])
            except ValueError:
                continue
    if size is None or size < 2:
        raise ValueError("不是有效的 3D .cube（缺少 LUT_3D_SIZE）")
    if len(data) != size ** 3:
        raise ValueError(f".cube 数据点数 {len(data)} 与尺寸 {size}（需 {size ** 3}）不符")
    # .cube 行序：红最快、绿次之、蓝最慢 → reshape 后 lut[蓝,绿,红,3]
    lut = torch.tensor(data, dtype=torch.float32).reshape(size, size, size, 3)
    return {"size": size, "domain_min": domain_min, "domain_max": domain_max, "lut": lut}


def load_lut(name: str) -> dict[str, Any]:
    path = lut_dir() / str(name)
    if not path.is_file():
        raise ValueError(f"未找到 LUT 文件：{name}（请把 .cube 放进 luts 目录）")
    return parse_cube(path.read_text(encoding="utf-8", errors="replace"))


def apply_lut3d(rgb: torch.Tensor, parsed: dict[str, Any]) -> torch.Tensor:
    """rgb [B,3,H,W]∈[0,1] → 三线性插值采样 LUT，返回同形状。"""
    size = int(parsed["size"])
    lut = parsed["lut"].to(device=rgb.device, dtype=torch.float32)
    dmin = torch.tensor(parsed["domain_min"], device=rgb.device, dtype=torch.float32).view(1, 3, 1, 1)
    dmax = torch.tensor(parsed["domain_max"], device=rgb.device, dtype=torch.float32).view(1, 3, 1, 1)
    span = (dmax - dmin).clamp_min(1e-6)
    scaled = ((rgb - dmin) / span).clamp(0.0, 1.0) * (size - 1)
    r, g, b = scaled[:, 0], scaled[:, 1], scaled[:, 2]

    def axis(v):
        lo = v.floor().long().clamp(0, size - 1)
        hi = (lo + 1).clamp(0, size - 1)
        frac = (v - lo.to(v.dtype)).clamp(0.0, 1.0)
        return lo, hi, frac

    r0, r1, fr = axis(r)
    g0, g1, fg = axis(g)
    b0, b1, fb = axis(b)
    fr = fr.unsqueeze(-1)
    fg = fg.unsqueeze(-1)
    fb = fb.unsqueeze(-1)

    c00 = lut[b0, g0, r0] * (1 - fr) + lut[b0, g0, r1] * fr
    c01 = lut[b0, g1, r0] * (1 - fr) + lut[b0, g1, r1] * fr
    c10 = lut[b1, g0, r0] * (1 - fr) + lut[b1, g0, r1] * fr
    c11 = lut[b1, g1, r0] * (1 - fr) + lut[b1, g1, r1] * fr
    c0 = c00 * (1 - fg) + c01 * fg
    c1 = c10 * (1 - fg) + c11 * fg
    out = c0 * (1 - fb) + c1 * fb
    return out.permute(0, 3, 1, 2).clamp(0.0, 1.0)


# ── 曲线 ─────────────────────────────────────────────────────
def parse_curve(raw: Any) -> list[list[float]]:
    if isinstance(raw, list):
        points = raw
    else:
        try:
            points = json.loads(str(raw or ""))
        except (ValueError, TypeError):
            points = []
    if not isinstance(points, list):
        return [[0.0, 0.0], [1.0, 1.0]]
    cleaned = []
    for point in points:
        try:
            x, y = float(point[0]), float(point[1])
        except (TypeError, ValueError, IndexError):
            continue
        cleaned.append([max(0.0, min(1.0, x)), max(0.0, min(1.0, y))])
    return cleaned or [[0.0, 0.0], [1.0, 1.0]]


def curve_lut(points: list[list[float]]) -> torch.Tensor:
    """控制点 → 256 级查表（分段线性，端点外夹取）。"""
    pts = sorted(((float(x), float(y)) for x, y in points), key=lambda p: p[0])
    if len(pts) < 2:
        pts = [(0.0, 0.0), (1.0, 1.0)]
    xs = [p[0] for p in pts]
    ys = [p[1] for p in pts]
    table = []
    for i in range(256):
        x = i / 255.0
        if x <= xs[0]:
            y = ys[0]
        elif x >= xs[-1]:
            y = ys[-1]
        else:
            j = 0
            while j < len(xs) - 1 and xs[j + 1] < x:
                j += 1
            x0, x1 = xs[j], xs[j + 1]
            t = (x - x0) / (x1 - x0) if x1 > x0 else 0.0
            y = ys[j] + (ys[j + 1] - ys[j]) * t
        table.append(max(0.0, min(1.0, y)))
    return torch.tensor(table, dtype=torch.float32)


def apply_curve(image: torch.Tensor, channel: str, points: list[list[float]]) -> torch.Tensor:
    """image [B,H,W,C]∈[0,1]，按通道查表；保留 alpha。"""
    table = curve_lut(points).to(image.device)
    rgb = image[..., :3].to(torch.float32)
    idx = (rgb.clamp(0.0, 1.0) * 255).round().long()
    mapped = table[idx]
    if channel in ("红", "绿", "蓝"):
        ci = {"红": 0, "绿": 1, "蓝": 2}[channel]
        out_rgb = rgb.clone()
        out_rgb[..., ci] = mapped[..., ci]
    else:
        out_rgb = mapped
    out = image.clone().to(torch.float32)
    out[..., :3] = out_rgb
    return out.to(dtype=image.dtype)


# ── 图像/视频通配处理 ─────────────────────────────────────────
def _process_image(image: torch.Tensor, fn) -> torch.Tensor:
    if not isinstance(image, torch.Tensor) or image.ndim != 4:
        raise TypeError("调色图像必须使用 ComfyUI 的 [batch, height, width, channels] 格式")
    if int(image.shape[-1]) < 3:
        raise ValueError("调色需要至少包含 RGB 三个通道")
    with torch.no_grad():
        return fn(image)


def process_media(media: Any, fn) -> Any:
    if isinstance(media, torch.Tensor):
        return _process_image(media, fn)
    components = components_for_video(media)
    images = _process_image(components.images, fn)
    return replace_video_frames(media, images)


def _lut_image_fn(parsed: dict[str, Any], strength: float):
    t = max(0.0, min(100.0, float(strength))) / 100.0

    def fn(image: torch.Tensor) -> torch.Tensor:
        if t <= 0:
            return image
        rgb = image[..., :3].movedim(-1, 1).to(torch.float32)
        graded = apply_lut3d(rgb, parsed)
        mixed = rgb * (1 - t) + graded * t
        mixed = mixed.movedim(1, -1)
        out = image.clone().to(torch.float32)
        out[..., :3] = mixed
        return out.to(dtype=image.dtype)

    return fn


class QQLutGrading:
    CATEGORY = "QQ/LR 调色"
    FUNCTION = "apply"
    RETURN_TYPES = (WslAnyType,)
    RETURN_NAMES = ("媒体",)
    DESCRIPTION = "加载 .cube 3D LUT 调色，按强度与原图混合；支持图像与视频，保留 alpha。LUT 放在 user/QQ_ComfyUI_Tools/luts。"

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "media": (WslAnyType,),
                "lut": (scan_lut_names(),),
                "强度": ("FLOAT", {"default": 100.0, "min": 0.0, "max": 100.0, "step": 1.0}),
            },
        }

    @staticmethod
    def apply(media, lut, 强度=100.0):
        parsed = load_lut(lut)
        return (process_media(media, _lut_image_fn(parsed, 强度)),)


class QQCurvesGrading:
    CATEGORY = "QQ/LR 调色"
    FUNCTION = "apply"
    RETURN_TYPES = (WslAnyType,)
    RETURN_NAMES = ("媒体",)
    DESCRIPTION = "RGB/单通道曲线调色（控制点查表）；支持图像与视频，保留 alpha。曲线由前端编辑器写入。"

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "media": (WslAnyType,),
                "通道": (["RGB", "红", "绿", "蓝"],),
                "曲线JSON": ("STRING", {"default": "[[0,0],[1,1]]", "multiline": False}),
            },
        }

    @staticmethod
    def apply(media, 通道="RGB", 曲线JSON="[[0,0],[1,1]]"):
        points = parse_curve(曲线JSON)
        return (process_media(media, lambda img: apply_curve(img, 通道, points)),)


# ── LUT 列表/上传路由 ─────────────────────────────────────────
def register() -> None:
    try:
        from aiohttp import web
        from server import PromptServer
    except Exception:
        return
    server = getattr(PromptServer, "instance", None)
    routes = getattr(server, "routes", None) if server is not None else None
    if routes is None or getattr(server, "_qq_lut_routes", False):
        return

    @routes.get("/qq_luts/list")
    async def list_luts(request):
        return web.json_response({"luts": scan_lut_names(), "dir": str(lut_dir())})

    @routes.post("/qq_luts/upload")
    async def upload_lut(request):
        try:
            form = await request.post()
            file = form.get("file")
            if file is None or not getattr(file, "filename", ""):
                return web.json_response({"error": "缺少文件"}, status=400)
            name = Path(file.filename).name
            if not name.lower().endswith(".cube"):
                return web.json_response({"error": "只接受 .cube 文件"}, status=400)
            target = lut_dir() / name
            with open(target, "wb") as handle:
                handle.write(file.file.read())
            return web.json_response({"ok": True, "name": name})
        except Exception as exc:
            return web.json_response({"error": str(exc)}, status=500)

    server._qq_lut_routes = True


NODE_CLASS_MAPPINGS = {"QQLutGrading": QQLutGrading, "QQCurvesGrading": QQCurvesGrading}
NODE_DISPLAY_NAME_MAPPINGS = {"QQLutGrading": "QQ-LUT调色", "QQCurvesGrading": "QQ-曲线调色"}
